begin;

create temporary table coding_question_seed (
  slug text not null,
  title text not null,
  problem_statement text not null,
  difficulty text not null,
  topic_tags text[] not null,
  constraints jsonb not null,
  examples jsonb not null,
  starter_code_by_language jsonb not null,
  points integer not null
) on commit drop;

insert into coding_question_seed
select seed.slug, seed.title, seed.problem_statement, seed.difficulty, seed.topic_tags,
  seed.constraints, seed.examples, seed.starter_code_by_language, seed.points
from jsonb_to_recordset($seed$
[{"slug":"balanced-bracket-strings","title":"Generate Balanced Bracket Strings","problem_statement":"Implement balancedBracketStrings(pairs: int). Return every string containing exactly pairs opening and closing parentheses in which every prefix has at least as many opens as closes. Return the empty string as the sole answer when pairs is zero.","difficulty":"Medium","topic_tags":["Recursion","Backtracking","Strings"],"constraints":["0 <= pairs <= 10","Output strings must be unique and lexicographically ordered"],"examples":[{"input":"pairs = 3","output":"[\"((()))\",\"(()())\",\"(())()\",\"()(())\",\"()()()\"]"},{"input":"pairs = 2","output":"[\"(())\",\"()()\"]"}],"starter_code_by_language":{"JavaScript":"function balancedBracketStrings(pairs) {\n  // Implement the behavior described in the prompt.\n  return [];\n}","Python":"def balanced_bracket_strings(pairs):\n    # Implement the behavior described in the prompt.\n    return []","Java":"public static List<String> balancedBracketStrings(int pairs) {\n    // Implement the behavior described in the prompt.\n    return new ArrayList<>();\n}","C++":"vector<string> balancedBracketStrings(int pairs) {\n    // Implement the behavior described in the prompt.\n    return {};\n}"},"points":150},{"slug":"combination-sum-unbounded","title":"Unlimited Candidate Combination Sum","problem_statement":"Implement combinationSumUnbounded(candidates: int[], target: int). Return all unique nondecreasing combinations that sum to target; each candidate may be reused any number of times. Return combinations in lexicographic order and return an empty list if no combination exists.","difficulty":"Medium","topic_tags":["Recursion","Backtracking","Combinations"],"constraints":["1 <= candidates.length <= 20","Candidates are distinct positive integers","0 <= target <= 500"],"examples":[{"input":"candidates = [2,3,6,7], target = 7","output":"[[2,2,3],[7]]"},{"input":"candidates = [2,3,5], target = 8","output":"[[2,2,2,2],[2,3,3],[3,5]]"}],"starter_code_by_language":{"JavaScript":"function combinationSumUnbounded(candidates, target) {\n  // Implement the behavior described in the prompt.\n  return [];\n}","Python":"def combination_sum_unbounded(candidates, target):\n    # Implement the behavior described in the prompt.\n    return []","Java":"public static List<List<Integer>> combinationSumUnbounded(int[] candidates, int target) {\n    // Implement the behavior described in the prompt.\n    return new ArrayList<>();\n}","C++":"vector<vector<int>> combinationSumUnbounded(const vector<int>& candidates, int target) {\n    // Implement the behavior described in the prompt.\n    return {};\n}"},"points":150},{"slug":"palindrome-partitioning","title":"Partition a String into Palindromes","problem_statement":"Implement palindromePartitioning(text: String). Return every partition of text into nonempty palindromic substrings. For the empty string return one empty partition.","difficulty":"Medium","topic_tags":["Recursion","Backtracking","Strings"],"constraints":["0 <= text.length <= 16","Input contains lowercase English letters","Partitions are ordered by increasing first-cut position"],"examples":[{"input":"text = \"aab\"","output":"[[\"a\",\"a\",\"b\"],[\"aa\",\"b\"]]"},{"input":"text = \"aba\"","output":"[[\"a\",\"b\",\"a\"],[\"aba\"]]"}],"starter_code_by_language":{"JavaScript":"function palindromePartitioning(text) {\n  // Implement the behavior described in the prompt.\n  return [];\n}","Python":"def palindrome_partitioning(text):\n    # Implement the behavior described in the prompt.\n    return []","Java":"public static List<List<String>> palindromePartitioning(String text) {\n    // Implement the behavior described in the prompt.\n    return new ArrayList<>();\n}","C++":"vector<vector<string>> palindromePartitioning(const string& text) {\n    // Implement the behavior described in the prompt.\n    return {};\n}"},"points":150},{"slug":"restore-ip-addresses","title":"Restore Valid IPv4 Addresses","problem_statement":"Implement restoreIpAddresses(digits: String). Insert exactly three dots into digits to form all valid IPv4 addresses. Each segment must be in [0,255]; return addresses in lexicographic order without duplicates.","difficulty":"Medium","topic_tags":["Recursion","Backtracking","Parsing"],"constraints":["4 <= digits.length <= 12","digits contains only decimal digits","Address segments cannot have leading zeroes except the segment 0"],"examples":[{"input":"digits = \"25525511135\"","output":"[\"255.255.11.135\",\"255.255.111.35\"]"},{"input":"digits = \"0000\"","output":"[\"0.0.0.0\"]"}],"starter_code_by_language":{"JavaScript":"function restoreIpAddresses(digits) {\n  // Implement the behavior described in the prompt.\n  return [];\n}","Python":"def restore_ip_addresses(digits):\n    # Implement the behavior described in the prompt.\n    return []","Java":"public static List<String> restoreIpAddresses(String digits) {\n    // Implement the behavior described in the prompt.\n    return new ArrayList<>();\n}","C++":"vector<string> restoreIpAddresses(const string& digits) {\n    // Implement the behavior described in the prompt.\n    return {};\n}"},"points":150},{"slug":"word-break-sentences","title":"Compose All Dictionary Sentences","problem_statement":"Implement wordBreakSentences(text: String, words: String[]). Return every sentence that splits text into dictionary words, joining words with one space. Return results in lexicographic order; an empty text has one empty sentence.","difficulty":"Hard","topic_tags":["Recursion","Backtracking","Memoization"],"constraints":["0 <= text.length <= 24","1 <= words.length <= 1000","Dictionary words are nonempty lowercase strings"],"examples":[{"input":"text = \"catsanddog\", words = [\"cat\",\"cats\",\"and\",\"sand\",\"dog\"]","output":"[\"cat sand dog\",\"cats and dog\"]"},{"input":"text = \"pineapplepenapple\", words = [\"apple\",\"pen\",\"applepen\",\"pine\",\"pineapple\"]","output":"[\"pine apple pen apple\",\"pine applepen apple\",\"pineapple pen apple\"]"}],"starter_code_by_language":{"JavaScript":"function wordBreakSentences(text, words) {\n  // Implement the behavior described in the prompt.\n  return [];\n}","Python":"def word_break_sentences(text, words):\n    # Implement the behavior described in the prompt.\n    return []","Java":"public static List<String> wordBreakSentences(String text, String[] words) {\n    // Implement the behavior described in the prompt.\n    return new ArrayList<>();\n}","C++":"vector<string> wordBreakSentences(const string& text, const vector<string>& words) {\n    // Implement the behavior described in the prompt.\n    return {};\n}"},"points":200},{"slug":"target-sign-expressions","title":"Build Expressions with Target Signs","problem_statement":"Implement targetSignExpressions(values: int[], target: int). For each value choose either a plus or minus sign, preserving array order. Return the number of sign assignments whose resulting sum equals target.","difficulty":"Medium","topic_tags":["Recursion","Backtracking","Counting"],"constraints":["0 <= values.length <= 20","0 <= values[i] <= 1000","The answer fits in a signed 64-bit integer"],"examples":[{"input":"values = [1,1,1,1,1], target = 3","output":"5"},{"input":"values = [0,0], target = 0","output":"4"}],"starter_code_by_language":{"JavaScript":"function targetSignExpressions(values, target) {\n  // Implement the behavior described in the prompt.\n  return 0;\n}","Python":"def target_sign_expressions(values, target):\n    # Implement the behavior described in the prompt.\n    return 0","Java":"public static long targetSignExpressions(int[] values, int target) {\n    // Implement the behavior described in the prompt.\n    return 0L;\n}","C++":"long targetSignExpressions(const vector<int>& values, int target) {\n    // Implement the behavior described in the prompt.\n    return 0LL;\n}"},"points":150},{"slug":"factor-combinations","title":"Factorizations into Proper Factors","problem_statement":"Implement factorCombinations(n: int). Return every factorization of n into at least two integers greater than one, with factors in nondecreasing order and results lexicographically ordered. Do not include n as a one-factor result.","difficulty":"Medium","topic_tags":["Recursion","Backtracking","Factorization"],"constraints":["1 <= n <= 100000","Each factor is at least 2","Factors in each result are nondecreasing"],"examples":[{"input":"n = 16","output":"[[2,2,2,2],[2,2,4],[2,8],[4,4]]"},{"input":"n = 32","output":"[[2,2,2,2,2],[2,2,2,4],[2,2,8],[2,4,4],[2,16],[4,8]]"}],"starter_code_by_language":{"JavaScript":"function factorCombinations(n) {\n  // Implement the behavior described in the prompt.\n  return [];\n}","Python":"def factor_combinations(n):\n    # Implement the behavior described in the prompt.\n    return []","Java":"public static List<List<Integer>> factorCombinations(int n) {\n    // Implement the behavior described in the prompt.\n    return new ArrayList<>();\n}","C++":"vector<vector<int>> factorCombinations(int n) {\n    // Implement the behavior described in the prompt.\n    return {};\n}"},"points":150},{"slug":"gray-code-cycle","title":"Construct a Gray Code Cycle","problem_statement":"Implement grayCodeCycle(bits: int). Return a cyclic ordering of all bit strings of length bits as integers, starting with 0, where each consecutive pair including the last and first differs in exactly one bit. Use the reflected recursive construction so the result is deterministic.","difficulty":"Medium","topic_tags":["Recursion","Backtracking","Bit Manipulation"],"constraints":["1 <= bits <= 16","The first code must be zero","Adjacent cyclic codes differ in one bit"],"examples":[{"input":"bits = 2","output":"[0,1,3,2]"},{"input":"bits = 3","output":"[0,1,3,2,6,7,5,4]"}],"starter_code_by_language":{"JavaScript":"function grayCodeCycle(bits) {\n  // Implement the behavior described in the prompt.\n  return [];\n}","Python":"def gray_code_cycle(bits):\n    # 