int>& values, int buckets) {\n    // Implement the behavior described in the prompt.\n    return false;\n}"},"points":200},{"slug":"match-pattern-with-bijection","title":"Match a Pattern to a String","problem_statement":"Implement matchPatternWithBijection(pattern: String, text: String). Return whether each pattern symbol can map to one nonempty substring so that the pattern expands exactly to text. Distinct symbols must map to distinct substrings.","difficulty":"Hard","topic_tags":["Recursion","Backtracking","Bijection"],"constraints":["1 <= pattern.length <= 10","1 <= text.length <= 30","Pattern symbols are lowercase letters"],"examples":[{"input":"pattern = \"abba\", text = \"redbluebluered\"","output":"true"},{"input":"pattern = \"ab\", text = \"aa\"","output":"false"}],"starter_code_by_language":{"JavaScript":"function matchPatternWithBijection(pattern, text) {\n  // Implement the behavior described in the prompt.\n  return false;\n}","Python":"def match_pattern_with_bijection(pattern, text):\n    # Implement the behavior described in the prompt.\n    return False","Java":"public static boolean matchPatternWithBijection(String pattern, String text) {\n    // Implement the behavior described in the prompt.\n    return false;\n}","C++":"bool matchPatternWithBijection(const string& pattern, const string& text) {\n    // Implement the behavior described in the prompt.\n    return false;\n}"},"points":200},{"slug":"expression-insert-operators","title":"Insert Operators to Reach a Target","problem_statement":"Implement expressionInsertOperators(digits: String, target: int). Insert +, -, or * between digits, or concatenate adjacent digits, to create expressions evaluating to target. Multiplication has standard precedence; return expressions lexicographically.","difficulty":"Hard","topic_tags":["Recursion","Backtracking","Expression Evaluation"],"constraints":["1 <= digits.length <= 10","digits contains decimal digits","No operand may have a leading zero unless it is exactly 0"],"examples":[{"input":"digits = \"123\", target = 6","output":"[\"1*2*3\",\"1+2+3\"]"},{"input":"digits = \"105\", target = 5","output":"[\"1*0+5\",\"10-5\"]"}],"starter_code_by_language":{"JavaScript":"function expressionInsertOperators(digits, target) {\n  // Implement the behavior described in the prompt.\n  return [];\n}","Python":"def expression_insert_operators(digits, target):\n    # Implement the behavior described in the prompt.\n    return []","Java":"public static List<String> expressionInsertOperators(String digits, int target) {\n    // Implement the behavior described in the prompt.\n    return new ArrayList<>();\n}","C++":"vector<string> expressionInsertOperators(const string& digits, int target) {\n    // Implement the behavior described in the prompt.\n    return {};\n}"},"points":200},{"slug":"remove-minimum-invalid-parentheses","title":"Remove the Fewest Invalid Parentheses","problem_statement":"Implement removeMinimumInvalidParentheses(text: String). Remove the minimum number of parentheses so the remaining string is balanced, preserving all other characters. Return distinct answers in lexicographic order.","difficulty":"Hard","topic_tags":["Recursion","Backtracking","Strings"],"constraints":["0 <= text.length <= 18","text contains lowercase letters and parentheses","Return all distinct valid results using the minimum removals"],"examples":[{"input":"text = \"()())()\"","output":"[\"(())()\",\"()()()\"]"},{"input":"text = \"(a)())()\"","output":"[\"(a())()\",\"(a)()()\"]"}],"starter_code_by_language":{"JavaScript":"function removeMinimumInvalidParentheses(text) {\n  // Implement the behavior described in the prompt.\n  return [];\n}","Python":"def remove_minimum_invalid_parentheses(text):\n    # Implement the behavior described in the prompt.\n    return []","Java":"public static List<String> removeMinimumInvalidParentheses(String text) {\n    // Implement the behavior described in the prompt.\n    return new ArrayList<>();\n}","C++":"vector<string> removeMinimumInvalidParentheses(const string& text) {\n    // Implement the behavior described in the prompt.\n    return {};\n}"},"points":200},{"slug":"choose-nonadjacent-indices","title":"Choose Nonadjacent Indices","problem_statement":"Implement chooseNonadjacentIndices(length: int, count: int). Return all increasing count-element index lists from [0,length) such that no two chosen indices are adjacent.","difficulty":"Medium","topic_tags":["Recursion","Backtracking","Combinations"],"constraints":["0 <= length <= 30","0 <= count <= length","Chosen indices are zero-based"],"examples":[{"input":"length = 5, count = 2","output":"[[0,2],[0,3],[0,4],[1,3],[1,4],[2,4]]"},{"input":"length = 4, count = 2","output":"[[0,2],[0,3],[1,3]]"}],"starter_code_by_language":{"JavaScript":"function chooseNonadjacentIndices(length, count) {\n  // Implement the behavior described in the prompt.\n  return [];\n}","Python":"def choose_nonadjacent_indices(length, count):\n    # Implement the behavior described in the prompt.\n    return []","Java":"public static List<List<Integer>> chooseNonadjacentIndices(int length, int count) {\n    // Implement the behavior described in the prompt.\n    return new ArrayList<>();\n}","C++":"vector<vector<int>> chooseNonadjacentIndices(int length, int count) {\n    // Implement the behavior described in the prompt.\n    return {};\n}"},"points":150},{"slug":"abbreviation-variants","title":"Generate Generalized Abbreviations","problem_statement":"Implement abbreviationVariants(word: String). Replace any non-overlapping runs of letters with their run length, leaving the other letters unchanged. Return all generalized abbreviations in lexicographic order.","difficulty":"Medium","topic_tags":["Recursion","Backtracking","Strings"],"constraints":["0 <= word.length <= 15","Input contains lowercase letters","Numbers in an abbreviation cannot be adjacent"],"examples":[{"input":"word = \"bat\"","output":"[\"1a1\",\"1at\",\"2t\",\"3\",\"b1t\",\"ba1