or described in the prompt.\n    return new ArrayList<>();\n}","C++":"vector<vector<string>> allShortestWordLadders(const string& begin, const string& end, const vector<string>& dictionary) {\n    // Implement the behavior described in the prompt.\n    return {};\n}"},"points":200}]
$seed$::jsonb) as seed(
  slug text,
  title text,
  problem_statement text,
  difficulty text,
  topic_tags text[],
  constraints jsonb,
  examples jsonb,
  starter_code_by_language jsonb,
  points integer
);

do $validate_seed$
declare
  row_count integer;
begin
  select count(*) into row_count from coding_question_seed;
  if row_count <> 20 then
    raise exception 'Expected exactly 20 recursion-backtracking seed questions; found %', row_count;
  end if;
  if (select count(distinct slug) from coding_question_seed) <> 20
     or (select count(distinct title) from coding_question_seed) <> 20
     or (select count(distinct problem_statement) from coding_question_seed) <> 20 then
    raise exception 'The recursion-backtracking seed must have 20 unique slugs, titles, and specifications';
  end if;
  if exists (
    select 1 from coding_question_seed
    where slug !~ '^[a-z0-9]+(-[a-z0-9]+)*$'
       or char_length(btrim(title)) not between 1 and 200
       or char_length(btrim(problem_statement)) not between 1 and 12000
       or problem_statement ~* '(placeholder|coming soon|lorem ipsum|todo)'
       or difficulty not in ('Easy', 'Medium', 'Hard')
       or jsonb_typeof(constraints) <> 'array'
       or jsonb_array_length(constraints) < 2
       or jsonb_typeof(examples) <> 'array'
       or jsonb_array_length(examples) < 2
       or exists (
         select 1 from jsonb_array_elements(examples) as example_entry(example_json)
         where jsonb_typeof(example_entry.example_json) <> 'object'
            or not (example_entry.example_json ?& array['input', 'output'])
            or coalesce(example_entry.example_json ->> 'input', '') = ''
            or coalesce(example_entry.example_json ->> 'output', '') = ''
            or btrim(example_entry.example_json ->> 'output') in ('[]', '[null]', 'null', '""')
       )
       or jsonb_typeof(starter_code_by_language) <> 'object'
       or not (starter_code_by_language ?& array['JavaScript', 'Python', 'Java', 'C++'])
       or exists (
         select 1 from jsonb_each(starter_code_by_language) as starter_entry(language_key, language_code)
         where jsonb_typeof(starter_entry.language_code) <> 'string'
            or starter_entry.language_code #>> '{}' = ''
       )
       or cardinality(topic_tags) = 0
       or jsonb_array_length(constraints) = 0
       or points not between 0 and 1000
  ) then
    raise exception 'Invalid recursion-backtracking question seed entry';
  end if;
  if exists (
    select 1 from coding_question_seed seed
    where seed.slug = any (array['permutations','subset-sum','n-queens','word-search','letter-combinations','binary-strings-length-n','count-grid-paths'])
  ) and 'recursion-backtracking' = 'recursion-backtracking' then
    raise exception 'The recursion seed collides with an existing question slug';
  end if;
  if exists (
    select 1 from coding_question_seed seed
    where seed.slug = any (array['climbing-stairs','coin-change','house-robber','longest-palindrome-subsequence','job-scheduling','equal-subset-partition','min-cost-climbing-stairs'])
  ) and 'recursion-backtracking' = 'dynamic-programming' then
    raise exception 'The dynamic-programming seed collides with an existing question slug';
  end if;
  if not exists (
    select 1 from public.coding_test_sets
    where slug = 'recursion-backtracking' and publication_status = 'published'
  ) then
    raise exception 'Published recursion-backtracking collection not found';
  end if;
end;
$validate_seed$;

with question_rows as (
  select collection.id as collection_id, seed.*,
    coalesce(existing.max_order, 0)
      + row_number() over (order by seed.slug)::integer as question_order
  from coding_question_seed seed
  join public.coding_test_sets collection
    on collection.slug = 'recursion-backtracking'
   and collection.publication_status = 'published'
  cross join lateral (
    select max(question.question_order) as max_order
    from public.coding_questions question
    where question.collection_id = collection.id
  ) existing
)
insert into public.coding_questions (
  collection_id, slug, title, problem_statement, difficulty, topic_tags,
  constraints, examples, starter_code_by_language, points, publication_status, question_order
)
select collection_id, slug, title, problem_statement, difficulty, topic_tags,
  constraints, examples, starter_code_by_language, points, 'published', question_order
from question_rows
on conflict (collection_id, slug) do nothing;

insert into public.coding_test_cases (question_id, case_order, test_input, expected_output, visibility)
select question.id, example.ordinality::integer,
  example.value ->> 'input', example.value ->> 'output', 'visible'
from coding_question_seed seed
join public.coding_test_sets collection on collection.slug = 'recursion-backtracking'
join public.coding_questions question
  on question.collection_id = collection.id and question.slug = seed.slug
cross join lateral jsonb_array_elements(seed.examples)
  with ordinality as example(value, ordinality)
on conflict (question_id, case_order) do nothing;

commit;
